insert into practice_exercises (id, subject_name, level, title, source) values
  ('ff6c0620-e9c1-438d-96d7-72cb9a17e7af', $$Natuurkunde$$, $$HAVO$$, $$Straling tijdens vliegen$$, $$HAVO Natuurkunde 2022-II$$),
  ('bf175db8-2e60-4276-b45a-6f2571d2ac61', $$Natuurkunde$$, $$HAVO$$, $$Ruimtepuin$$, $$HAVO Natuurkunde 2022-II$$),
  ('e3056f91-1f05-49ed-baa7-6f261397f9cd', $$Natuurkunde$$, $$HAVO$$, $$Kreukelzone$$, $$HAVO Natuurkunde 2022-II$$),
  ('d949dcf8-85a4-4908-93fa-e47ed7c7e90f', $$Natuurkunde$$, $$HAVO$$, $$Ocarina$$, $$HAVO Natuurkunde 2022-II$$),
  ('6e21d04c-7333-4cb0-a460-544ad5c48fda', $$Natuurkunde$$, $$HAVO$$, $$Koffiepercolator$$, $$HAVO Natuurkunde 2022-II$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('0f81d71f-eb01-456a-996f-db1fa2328c5f', 'ff6c0620-e9c1-438d-96d7-72cb9a17e7af', $$intro kosmische straling tijdens vliegen; wand vliegtuig 2,2 mm, gammastraling 2,4·10²⁰ Hz$$, $$natuurkunde-havo-2022-ii-straling-tijdens-vliegen-context1.png$$, 496, $$Hoog in de atmosfeer ontstaan snelle neutronen en gammastraling door kosmische straling. Hoe hoger iemand zich in de atmosfeer bevindt, hoe groter de schadelijke invloed van deze straling is. Studenten hebben daarom onderzoek gedaan naar de ontvangen dosis als gevolg van snelle neutronen en gammastraling tijdens een vlucht in een vliegtuig.

De wand van een vliegtuig is gemaakt van aluminium met een dikte van 2,2 mm. De gammastraling heeft een frequentie van 2,4·10²⁰ Hz.$$, 'inline'),
  ('5218e9f6-c87c-41af-988c-851391875eea', 'ff6c0620-e9c1-438d-96d7-72cb9a17e7af', $$figuur 1 en 2 — bubbeldetector (buis met vloeistof) en test met Am-241/Be-9$$, $$natuurkunde-havo-2022-ii-straling-tijdens-vliegen-context2.png$$, 496, $$Net als gammastraling hebben de snelle neutronen ioniserende eigenschappen. Om snelle neutronen te detecteren wordt een zogenaamde bubbeldetector gebruikt. Dit is een doorzichtige buis gevuld met vloeistof. Als deze vloeistof wordt geraakt door snelle neutronen ontstaan er bellen in de vloeistof. Deze bellen blijven aanwezig tot de bellendetector gereset wordt. Zie figuren 1 en 2.

figuur 1: zwart-witfoto van twee bubbeldetectorbuizen; de linkerbuis vertoont enkele lange sporen, de rechterbuis vertoont dezelfde lange sporen plus veel kleine ronde bellen.
figuur 2: schematische tekening van twee bubbeldetectorbuizen waarin invallende neutronen (n) met stippellijnen zijn getekend die bij het raken van de vloeistof een bel (open cirkel) veroorzaken.

Om de bubbeldetector vóór de vlucht te testen, hebben de studenten hem naast een bron met Americium-241 en Beryllium-9 gelegd. Am-241 is een alfastraler.$$, 'inline'),
  ('d273170e-f432-4cc6-b386-08c6d94a45ad', 'ff6c0620-e9c1-438d-96d7-72cb9a17e7af', $$Beryllium-9 neemt alfadeeltje op; nieuw deeltje en snel neutron ontstaan$$, $$natuurkunde-havo-2022-ii-straling-tijdens-vliegen-context3.png$$, 496, $$Beryllium-9 neemt een alfadeeltje op. Hierbij ontstaan een nieuw deeltje en een snel neutron. Op de uitwerkbijlage staat een deel van deze reactie weergegeven.$$, 'inline'),
  ('d4722818-16fc-4697-9f23-cf37b2a4c7a4', 'ff6c0620-e9c1-438d-96d7-72cb9a17e7af', $$uitwerkbijlage vraag 3 — onvolledige kernreactievergelijking van Beryllium-9 met een alfadeeltje$$, $$natuurkunde-havo-2022-ii-straling-tijdens-vliegen-uitwerkbijlage-vraag3.png$$, 496, $$Uitwerkbijlage vraag 3: onvolledige reactievergelijking ₉...Be + ⁴₂He → ¹²...… + ⋯n, met open plekken voor het massagetal en atoomnummer van beryllium, het nieuwe deeltje en het massagetal/atoomnummer daarvan, die de leerling moet aanvullen.$$, 'uitwerkbijlage'),
  ('756c6b02-76bf-4066-bbbe-2b9ec018e544', 'ff6c0620-e9c1-438d-96d7-72cb9a17e7af', $$figuur 3 — bubbeldetector aan grond vs in vliegtuig; 3 bubbels per 5,0·10⁻⁸ Gy bij 1 MeV$$, $$natuurkunde-havo-2022-ii-straling-tijdens-vliegen-context4.png$$, 496, $$Snelle neutronen zijn in staat om door de wand van een vliegtuig te dringen. De studenten hebben de bubbeldetector meegenomen tijdens de vlucht om de ontvangen dosis als gevolg van de snelle neutronen te bepalen.
Een tweede, identieke bubbeldetector is ter controle achtergebleven op de grond. Beide detectoren zijn direct na de vlucht geanalyseerd. Zie figuur 3.

figuur 3: twee bubbeldetectorbuizen naast elkaar, gelabeld "aan het aardoppervlak" (met 1 bel) en "in het vliegtuig" (met 6 bellen).

In de technische gegevens van de gebruikte bubbeldetectoren staat:
Bij een neutronenergie van 1 MeV ontstaan 3 bubbels per 5,0·10⁻⁸ Gy ontvangen stralingsdosis.$$, 'inline'),
  ('1b857554-fe23-4343-83d0-fd7951b1d9ba', 'bf175db8-2e60-4276-b45a-6f2571d2ac61', $$figuur 1 — kunstenaar duidt ruimtepuin met lasers aan (hoogte 2,0·10⁵–2,0·10⁷ m); botsing 2009, baansnelheid 7,75·10³ m/s$$, $$natuurkunde-havo-2022-ii-ruimtepuin-context1.png$$, 496, $$Versleten satellieten en brokstukken van gebotste satellieten vliegen als ruimtepuin rond de aarde. In 2018 heeft een kunstenaar geprobeerd om mensen bewust te maken van dit ruimtepuin, dat vanaf de aarde onzichtbaar is. Hij heeft met lasers vanaf de grond de positie van ruimtepuin op hoogtes tussen 2,0·10⁵ m en 2,0·10⁷ m aangeduid. Zie een artist''s impression in figuur 1.

figuur 1: nachtfoto van een aantal felle, rechte lichtbundels die vanaf de grond schuin de lucht in schijnen, met een heldere lichtvlek (de maan) tussen de bundels.

In 2009 vond de eerste botsing tussen twee satellieten plaats. Door deze botsing ontstonden veel brokstukken die nu nog om de aarde cirkelen.
De baansnelheid van een van de satellieten in zijn cirkelbaan voor de botsing was 7,75·10³ m s⁻¹.$$, 'inline'),
  ('f0cea620-92af-4449-9c23-6e4d5e82417f', 'bf175db8-2e60-4276-b45a-6f2571d2ac61', $$figuur 2 — schema geostationaire baan en kerkhofbaan rond de aarde (niet op schaal)$$, $$natuurkunde-havo-2022-ii-ruimtepuin-context2.png$$, 496, $$Om botsingen te voorkomen wordt tegenwoordig al vóór de lancering van nieuwe satellieten nagedacht over het opruimen ervan aan het einde van de levensduur.
Een mogelijke oplossing voor een geostationaire satelliet is om hem aan het einde van zijn leven naar een speciale baan om de aarde te brengen: de kerkhofbaan. Zie figuur 2. Deze figuur is schematisch en niet op schaal.

figuur 2: schema met de aarde in het midden, een binnenste cirkel gelabeld "geostationaire baan" en een buitenste cirkel gelabeld "kerkhofbaan", met een gestippelde pijl die de overgang van de geostationaire baan naar de kerkhofbaan aangeeft.$$, 'inline'),
  ('7e6ba15c-f348-4be9-9cb3-072666c5a8a8', 'bf175db8-2e60-4276-b45a-6f2571d2ac61', $$overgang kerkhofbaan: 7,0 MJ arbeid, rendement 64%, stookwaarde 19,4·10⁶ J/kg, satellietmassa orde 100 kg$$, $$natuurkunde-havo-2022-ii-ruimtepuin-context3.png$$, 496, $$Voor de overgang van de geostationaire baan naar de kerkhofbaan moet 7,0 MJ arbeid worden verricht. Deze arbeid wordt geleverd door een stuwraket die brandstof verbrandt met een rendement van 64%. De brandstof die wordt gebruikt, heeft een stookwaarde van 19,4·10⁶ J kg⁻¹.
De orde van grootte van de massa van een kleine satelliet is 100 kg.$$, 'inline'),
  ('bd1e7139-7b2e-4283-b8de-155e91238c5a', 'bf175db8-2e60-4276-b45a-6f2571d2ac61', $$brokstukken: kerkhofbaan geen oplossing; laserbestraling remt af, brokstuk komt dichter bij aarde en verdampt door snelle temperatuurstijging$$, $$natuurkunde-havo-2022-ii-ruimtepuin-context4.png$$, 496, $$Voor brokstukken die zijn ontstaan na een botsing, is een kerkhofbaan sowieso geen oplossing. Een voorstel is om dit ruimtepuin op te ruimen door bestraling met zeer krachtige lasers vanaf de aarde.

Door de bestraling met lasers neemt de snelheid van een brokstuk een beetje af. Hierdoor komt het dichter bij de aarde en zal het uiteindelijk door een snelle toename van temperatuur verdampen.$$, 'inline'),
  ('9bf30b08-a521-4872-ad4b-0d3e70867b27', 'bf175db8-2e60-4276-b45a-6f2571d2ac61', $$laservermogen 1·10² J/s, brokstuk m=2 kg afremmen van 7,6·10³ naar 7,5·10³ m/s in 1 minuut$$, $$natuurkunde-havo-2022-ii-ruimtepuin-context5.png$$, 496, $$De lasers verrichten arbeid en remmen hierdoor een brokstuk af. Dergelijke opruimacties zijn al gemodelleerd door wetenschappers, maar zouden de lasers van de kunstenaar ook krachtig genoeg zijn om een brokstuk voldoende af te remmen?
De arbeid die deze lasers samen per seconde verrichten op het brokstuk is 1·10² J. De snelheid van dit brokstuk (m = 2 kg) moet worden verlaagd van 7,6·10³ m s⁻¹ naar 7,5·10³ m s⁻¹. De lasers raken het brokstuk in totaal 1 minuut.$$, 'inline'),
  ('91ff55c3-282f-47cd-a93d-fa0879854970', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$figuur 1 — karretje op helling, krachtsensor en afstandssensor voor botsproef$$, $$natuurkunde-havo-2022-ii-kreukelzone-context1.png$$, 496, $$Inzittenden van een auto worden tijdens een botsing onder andere beschermd door kreukelzones. Jeroen wil het effect van een kreukelzone tijdens een botsing onderzoeken door een karretje van een helling te laten rijden en tegen een zelfgemaakte krachtsensor te laten botsen. Met een afstandssensor bepaalt hij de plaats van het karretje op de baan tijdens een botsproef. Zie figuur 1.

figuur 1: foto van een hellende baan met onderaan een karretje tegen een krachtsensor en bovenaan een afstandssensor op de baan bevestigd.$$, 'inline'),
  ('a0953806-c224-4445-90c5-f3cffc8df8b5', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$Deel 1: de krachtsensor; figuur 2 — hefboom met draaipunt D, opstelling I (gewichten aan lange arm) en II (gewichten aan korte arm)$$, $$natuurkunde-havo-2022-ii-kreukelzone-context2.png$$, 496, $$Deel 1: de krachtsensor
Jeroen wil controleren wat de krachtsensor aangeeft voor krachten tot 25 N. Jeroen heeft 25 gewichten van 50 gram. Om tot 25 N te kunnen controleren gebruikt Jeroen een hefboom met draaipunt D waarmee hij met een staafje op de krachtsensor op tafel drukt. Hij kan hier twee verschillende opstellingen (I of II) voor gebruiken. Zie figuur 2. De massa van de hefboom en het staafje mogen verwaarloosd worden.

figuur 2: twee tekeningen van een hefboom met draaipunt D; in opstelling I hangen de gewichten dicht bij D en drukt de kracht F via de krachtsensor ver van D, in opstelling II hangen de gewichten ver van D en drukt de kracht F dicht bij D.$$, 'inline'),
  ('537f257c-1283-4acf-9eb9-a4545e3feb00', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$figuur 3 — serieschakeling R1 (krachtgevoelig) en R2 = 5,6 kΩ op 5,0 V; figuur 4 — Usensor tegen F$$, $$natuurkunde-havo-2022-ii-kreukelzone-context3.png$$, 496, $$De krachtsensor zelf bestaat uit een serieschakeling van een krachtgevoelige weerstand R1 en een ohmse weerstand R2 van 5,6 kΩ. De weerstand van R1 verandert als er een grotere of kleinere kracht op wordt uitgeoefend.

De spanningsbron levert 5,0 V. Zie figuur 3.

figuur 3: schakelschema met een spanningsbron van 5,0 V in serie met R1 (variabele weerstand) en R2 (5,6 kΩ); Usensor is de spanning over R2.

Jeroen heeft het verband tussen de spanning over R2 (de zogenaamde sensorspanning Usensor) en de kracht F op de sensor bepaald. Dit is weergegeven in figuur 4.

figuur 4: grafiek van Usensor (V, 0 tot 4,0) tegen F (N, 0 tot 25); een stijgende, naar onderen gebogen kromme die begint bij ongeveer 0,4 V bij F = 0 N en afvlakt naar ongeveer 3,75 V bij F = 25 N.$$, 'inline'),
  ('01c0a50f-7000-458e-b880-f8370d63f242', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$krachtsensor geeft ook zonder kracht al een beginspanning U0 groter dan 0 V$$, $$natuurkunde-havo-2022-ii-kreukelzone-context4.png$$, 496, $$Als er geen kracht op de krachtsensor werkt, geeft deze sensor toch al een beginspanning U0 die groter is dan 0 V.$$, 'inline'),
  ('04d15c42-a932-48de-aae6-9b6d8f8fb3f2', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$uitwerkbijlage vraag 11 — drie zinnen met toe/af en oneindig groot/nagenoeg nul om te omcirkelen$$, $$natuurkunde-havo-2022-ii-kreukelzone-uitwerkbijlage-vraag11.png$$, 496, $$Uitwerkbijlage vraag 11: "Als de krachtgevoelige weerstand R1 toeneemt, neemt de spanning over deze weerstand R1 toe / af.", "De sensorspanning Usensor over weerstand R2 neemt dan toe / af." en "Om de sensorspanning Usensor op 0 V uit te laten komen moet de krachtgevoelige weerstand R1 oneindig groot / nagenoeg nul worden.", met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('5d06856c-5dcd-4b84-9587-8cf594ecf7d6', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$Deel 2: de botsproef; figuur 5 — karretje (m=0,26 kg) in rust op helling, Fz op schaal, spanning UA groter dan U0$$, $$natuurkunde-havo-2022-ii-kreukelzone-context5.png$$, 496, $$Deel 2: de botsproef
Als het karretje in rust tegen de sensor staat, constateert Jeroen dat de krachtsensor al een bepaalde spanning UA geeft die groter is dan U0. Hij concludeert dat dat komt doordat het karretje op een helling staat. Zie figuur 5. De rolweerstandskracht wordt verwaarloosd.

figuur 5: tekening van een karretje in rust op een hellende baan tegen de krachtsensor, met de zwaartekracht Fz als verticale pijl op schaal getekend vanuit het karretje.

Het karretje heeft een massa van 0,26 kg.
Figuur 5 staat ook op de uitwerkbijlage. De zwaartekracht Fz is op schaal ingetekend. In deze situatie is de kracht F op de sensor even groot als de component van Fz parallel aan de helling.$$, 'inline'),
  ('7ba2e736-8c58-4417-b8c3-a6e4ce024a81', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$uitwerkbijlage vraag 12 — figuur 5 (karretje op helling met Fz) om de component langs de helling in te tekenen$$, $$natuurkunde-havo-2022-ii-kreukelzone-uitwerkbijlage-vraag12.png$$, 496, $$Uitwerkbijlage vraag 12: dezelfde tekening als figuur 5 van een karretje op een hellende baan met de zwaartekracht Fz als verticale pijl vanuit het zwaartepunt getekend, met ruimte om de component van Fz parallel aan de helling te construeren.$$, 'uitwerkbijlage'),
  ('77d848f2-2b28-4852-8c78-7b8f7d720a38', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$Jeroen test opstelling (m=0,26 kg); (x,t)-diagram van de test op de uitwerkbijlage$$, $$natuurkunde-havo-2022-ii-kreukelzone-context6.png$$, 496, $$Jeroen test de opstelling. Hij laat het karretje (m = 0,26 kg) van de helling rijden en tegen de krachtsensor botsen. Van deze test maakt hij een (x,t)-diagram. Dit (x,t)-diagram staat op de uitwerkbijlage.$$, 'inline'),
  ('c62a1288-3ce8-41c1-90f5-b4b520f314ed', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$uitwerkbijlage vraag 13 — (x,t)-diagram van de botsproef met invulruimte voor de bepaling$$, $$natuurkunde-havo-2022-ii-kreukelzone-uitwerkbijlage-vraag13.png$$, 496, $$Uitwerkbijlage vraag 13: (x,t)-diagram met x (m, 0 tot 0,7) op de verticale as en t (s, 0 tot 1,2) op de horizontale as; een stijgende kromme die na een piek bij ongeveer x = 0,59 m licht terugveert en vervolgens naar een constante waarde van ongeveer x = 0,58 m gaat, gevolgd door invulregels bij "Bepaling:" om de maximale kinetische energie te berekenen.$$, 'uitwerkbijlage'),
  ('ce4cdbe2-1ad6-4954-a483-f9df232b2df4', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$twee botsproeven met en zonder kreukelzone (luciferdoosje, figuur 6); (F,x)-diagrammen op uitwerkbijlage, zelfde snelheid$$, $$natuurkunde-havo-2022-ii-kreukelzone-context7.png$$, 496, $$Vervolgens voert Jeroen vanaf andere hoogtes twee vergelijkbare botsproeven uit. Hij laat het karretje naar beneden rijden en tegen de krachtsensor botsen. Eén keer botst het karretje direct tegen de sensor. Daarna botst het met een vervormbaar luciferdoosje als kreukelzone tussen het karretje en de krachtsensor. Zie figuur 6. De massa van het luciferdoosje is verwaarloosbaar.

figuur 6: foto van een karretje op de hellende baan met een luciferdoosje tussen het karretje en de krachtsensor bevestigd, als kreukelzone.

Van beide botsproeven maakt Jeroen een (F, x)-diagram. Hierin is x de plek van het karretje op de baan. Deze diagrammen staan vereenvoudigd op de uitwerkbijlage. De oppervlakte onder iedere grafiek is de arbeid die de krachtsensor heeft verricht om het karretje af te remmen.
Jeroen constateert dat de kreukelzone tijdens de botsing een deel van de energie van het karretje heeft geabsorbeerd. Beide botsingen vinden met dezelfde snelheid plaats.$$, 'inline'),
  ('8d120b8c-b49b-42ac-9c45-105b5312f970', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$uitwerkbijlage vraag 14 — (F,x)-diagrammen botsing zonder en met kreukelzone, met invulruimte voor de bepaling$$, $$natuurkunde-havo-2022-ii-kreukelzone-uitwerkbijlage-vraag14.png$$, 496, $$Uitwerkbijlage vraag 14: twee (F,x)-diagrammen met F (N, 0 tot 25) op de verticale as en x (m, 0,43 tot 0,51, onderbroken schaal) op de horizontale as. "botsing zonder kreukelzone": een rechte, stijgende lijn van (0,48; 0) naar (0,505; 24) gevolgd door een verticale lijn terug naar 0. "botsing met kreukelzone": een minder steile rechte lijn van (0,48; 0) naar (0,508; 11) gevolgd door een verticale lijn terug naar 0. Onder de diagrammen invulregels bij "Bepaling:" om de geabsorbeerde energie te berekenen.$$, 'uitwerkbijlage'),
  ('1698c7f5-61bc-4315-a8e2-46ed96866316', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$conclusies van Jeroen over afstand, tijdsduur en maximale kracht bij botsing met/zonder kreukelzone (tabel op uitwerkbijlage)$$, $$natuurkunde-havo-2022-ii-kreukelzone-context8.png$$, 496, $$Jeroen trekt naar aanleiding van zijn onderzoek een aantal conclusies over grootheden die kunnen veranderen door het gebruik van een kreukelzone. Deze conclusies staan op de uitwerkbijlage.$$, 'inline'),
  ('13be5ee2-9eeb-4586-b72d-470367bce96f', 'e3056f91-1f05-49ed-baa7-6f261397f9cd', $$uitwerkbijlage vraag 15 — tabel met drie conclusies van Jeroen (afstand, tijdsduur, max. kracht) en kolommen juist/onjuist$$, $$natuurkunde-havo-2022-ii-kreukelzone-uitwerkbijlage-vraag15.png$$, 496, $$Uitwerkbijlage vraag 15: tabel met drie conclusies van Jeroen — "De afgelegde afstand is tijdens een botsing met kreukelzone groter dan tijdens een botsing met hetzelfde snelheidsverschil zonder kreukelzone.", "De tijdsduur van een botsing met kreukelzone is even lang als de tijdsduur van een botsing met hetzelfde snelheidsverschil zonder kreukelzone." en "De maximale kracht op het karretje is tijdens een botsing met kreukelzone gelijk aan de maximale kracht op het karretje tijdens een botsing met hetzelfde snelheidsverschil zonder kreukelzone." — met bij elke conclusie kolommen "juist" en "onjuist" om aan te kruisen.$$, 'uitwerkbijlage'),
  ('449ee165-a786-46b3-9992-52b57b40d9c5', 'd949dcf8-85a4-4908-93fa-e47ed7c7e90f', $$figuur 1 en 2 — ocarina met hals en romp; figuur 3 — oscillogram van een gespeelde toon$$, $$natuurkunde-havo-2022-ii-ocarina-context1.png$$, 496, $$Een ocarina is een blaasinstrument dat bestaat uit een romp en een hals. De ocarina wordt aangeblazen door de hals. In de romp zitten diverse gaten die tijdens het spelen met de vingers kunnen worden afgesloten om verschillende tonen te maken. Zie figuren 1 en 2.

figuur 1: foto van een ovale, hartvormige ocarina met de hals en de romp met meerdere gaten aangewezen.
figuur 2: foto van een persoon die op een ocarina blaast, met de hals en de romp aangewezen.

Met de ocarina wordt een toon gespeeld. In figuur 3 staat het oscillogram van deze toon.

figuur 3: oscillogram met t (ms, 0 tot ongeveer 28) op de horizontale as; een regelmatig sinusvormig signaal met steeds dezelfde amplitude en periode, ongeveer 15 volledige trillingen zichtbaar.$$, 'inline'),
  ('bc23a05d-ab29-4fbf-9e07-c3b803d3cbab', 'd949dcf8-85a4-4908-93fa-e47ed7c7e90f', $$figuur 4 — massa-veersysteem model (luchtmassa m in de hals, veerconstante C van de lucht in de romp); trillingstijd 2,5·10⁻³ s, volume hals 1,9·10⁻⁵ m³$$, $$natuurkunde-havo-2022-ii-ocarina-context2.png$$, 496, $$Een ocarina produceert op een bijzondere manier geluid: hij werkt als een massa-veersysteem. In figuur 4 is een vereenvoudigd model van dit systeem van de ocarina uit figuur 1 weergegeven.

figuur 4: vier tekeningen van een ocarina met een massa m (het luchtblokje in de hals) in verschillende standen ten opzichte van de romp, gelabeld met de veerconstante C van de lucht in de romp.

De lucht in de hals heeft een massa (m). Deze massa wordt als constant beschouwd. De lucht in de hals trilt op en neer. Door de op- en neergaande beweging van de luchtmassa in de hals, werkt de lucht in de romp als een soort veer met veerconstante C die samengedrukt en uitgerekt wordt.

De ocarina brengt een bepaalde toon voort met een trillingstijd van 2,5·10⁻³ s. De lucht in de hals van de ocarina in figuur 1 heeft een volume van 1,9·10⁻⁵ m³.$$, 'inline'),
  ('f003d61d-1ac0-485d-97be-92b2f7a18c8d', 'd949dcf8-85a4-4908-93fa-e47ed7c7e90f', $$golflengte van het geluid van een ocarina is altijd ≥ de lengte van het instrument$$, $$natuurkunde-havo-2022-ii-ocarina-context3.png$$, 496, $$Voor de ocarina geldt dat de golflengte van het geluid altijd even groot als of groter dan de lengte van het instrument zal zijn.$$, 'inline'),
  ('bade1141-230f-4d85-aed5-f58e9bc6e3a4', 'd949dcf8-85a4-4908-93fa-e47ed7c7e90f', $$formule (1): T = k·√(V·d/A); definities A, d, V, k; volumeverandering tijdens afbakken$$, $$natuurkunde-havo-2022-ii-ocarina-context4.png$$, 496, $$Voor de trillingstijd T van een toon die een ocarina produceert, geldt:

T = k·√(V·d/A)  (1)

Hierin is:
− A de totale oppervlakte van de (niet-afgesloten) gaten;
− d de wanddikte van de ocarina;
− V het volume van de romp;
− k een constante.

Een ocarina wordt gemaakt van klei. Nadat de klei is gedroogd, wordt de ocarina verder afgebakken in een oven. Tijdens het afbakken wordt het volume van de romp van de ocarina iets kleiner en wordt de toon van de ocarina anders dan wanneer deze volumeverandering niet zou plaatsvinden. De wanddikte blijft bij benadering constant. Om na het bakken de juiste toonhoogte te krijgen, moet men een gat kleiner maken met klei of groter slijpen.$$, 'inline'),
  ('a2d4bf24-e8bb-485e-b6a9-5f88195ba342', 'd949dcf8-85a4-4908-93fa-e47ed7c7e90f', $$opmerking correctievoorschrift: bij vraag 19 altijd alle scorepunten toekennen (onduidelijk of A verandert tijdens afbakken)$$, $$natuurkunde-havo-2022-ii-ocarina-context5.png$$, 496, $$Voor vraag 19 moeten altijd alle scorepunten worden toegekend, ongeacht of er wel of geen antwoord gegeven is, en ongeacht het gegeven antwoord.

Toelichting: Er kan uit de tekst niet opgemaakt worden of A verandert tijdens het afbakken.$$, 'inline'),
  ('5f8f70f7-08d5-4cef-95c2-1669f6bf4d6f', '6e21d04c-7333-4cb0-a460-544ad5c48fda', $$figuur 1 — percolator met verlengsnoer; figuur 2 — sticker verlengsnoer (13 A afgerold / 4,4 A opgerold); vermogen 1,5 kW op 230 V$$, $$natuurkunde-havo-2022-ii-koffiepercolator-context1.png$$, 496, $$Een percolator is een apparaat dat in één keer een grote hoeveelheid koffie kan zetten en kan warmhouden.

figuur 1: foto van een percolator op een klaptafeltje naast een opgerold verlengsnoer op de grond.

Een percolator wordt met een verlengsnoer aangesloten op een stopcontact. Zie figuur 1.

Wanneer het verlengsnoer bij gebruik niet volledig is afgerold, ontstaat er brandgevaar bij overbelasting. Op het verlengsnoer is aangegeven hoeveel stroom er maximaal door de kabel mag lopen wanneer hij opgerold of afgerold wordt gebruikt. Zie figuur 2.

figuur 2: foto van een sticker op een kabelhaspel met de tekst "230V-/13A/25 meter", en de waarden "afgerold 13 A" en "opgerold 4,4 A".

Het vermogen van de koffiepercolator is tijdens het koffiezetten 1,5 kW. De koffiepercolator werkt op 230 V.$$, 'inline'),
  ('eac5bc57-cb52-4622-823d-b03ac1cf3bad', '6e21d04c-7333-4cb0-a460-544ad5c48fda', $$figuur 3 — (T,t)-diagram van de koffie (fase I t/m 94 °C, fase II erna); fase I: 3,0 L water, 1,5 kW$$, $$natuurkunde-havo-2022-ii-koffiepercolator-context2.png$$, 496, $$In figuur 3 is het (T,t)-diagram weergegeven van de koffie in een percolator.

figuur 3: (T,t)-diagram met T (°C, 0 tot 100) op de verticale as en t (minuten, 0 tot 500) op de horizontale as; de temperatuur stijgt snel van ongeveer 15 °C naar een piek van 94 °C (fase I, tot ongeveer t = 25 min, gemarkeerd met een stippellijn), en daalt daarna geleidelijk af naar een constante waarde van ongeveer 75 °C (fase II).

Tijdens fase I wordt de koffie gezet. Er wordt koffie gezet met 3,0 L water. De stofeigenschappen van koffie zijn gelijk aan die van water. Gedurende het koffiezetten is het vermogen van de koffiepercolator 1,5 kW.$$, 'inline'),
  ('051102d8-bae0-437b-8239-d3b46e3640e0', '6e21d04c-7333-4cb0-a460-544ad5c48fda', $$Pverlies (energieverlies per seconde aan omgeving); bij 94 °C schakelt apparaat over naar fase II; tabel over figuur 3 op uitwerkbijlage$$, $$natuurkunde-havo-2022-ii-koffiepercolator-context3.png$$, 496, $$De percolator staat warmte af aan de omgeving. Het energieverlies per seconde aan de omgeving wordt Pverlies genoemd. Zodra de koffie een temperatuur van 94 °C heeft bereikt is hij klaar en schakelt het apparaat over op een lager elektrisch vermogen om de koffie warm te houden. Dit is fase II in figuur 3.
Op de uitwerkbijlage staat een tabel over figuur 3.$$, 'inline'),
  ('d33aff0e-7733-4a47-b269-cb0ee1c2b404', '6e21d04c-7333-4cb0-a460-544ad5c48fda', $$uitwerkbijlage vraag 22 — tabel met Pelektrisch t.o.v. Pverlies op t=10, 100 en 500 minuten$$, $$natuurkunde-havo-2022-ii-koffiepercolator-uitwerkbijlage-vraag22.png$$, 496, $$Uitwerkbijlage vraag 22: tabel met kolommen "Pelektrisch > Pverlies", "Pelektrisch = Pverlies" en "Pelektrisch < Pverlies", met rijen "Op t = 10 min geldt:", "Op t = 100 min geldt:" en "Op t = 500 min geldt:", om per tijdstip aan te kruisen.$$, 'uitwerkbijlage'),
  ('52e0ac47-64ad-4e02-a028-90b8ee8c5731', '6e21d04c-7333-4cb0-a460-544ad5c48fda', $$figuur 4 — schakelschema met R1=35 Ω, R2=590 Ω, R3=590 Ω en schakelaar S op 230 V$$, $$natuurkunde-havo-2022-ii-koffiepercolator-context4.png$$, 496, $$De verwarming van de percolator bestaat uit drie weerstanden R1, R2 en R3. In figuur 4 is het schakelschema weergegeven van het systeem dat gebruikt wordt.

figuur 4: schakelschema met een bron van 230 V in serie met R1 (35 Ω); daarna vertakt de stroom naar een parallelcombinatie van R2 (590 Ω) en de serieschakeling van R3 (590 Ω) met schakelaar S.

Gedurende fase I is een groot vermogen ingeschakeld om te verwarmen. Gedurende fase II is een klein vermogen ingeschakeld om warm te houden. Het omschakelen van fase I naar fase II gebeurt door een (temperatuurgestuurde) schakelaar S.$$, 'inline'),
  ('40c44635-ca09-49b5-98e8-c4f488640674', '6e21d04c-7333-4cb0-a460-544ad5c48fda', $$ketel enkelwandig massief roestvrij staal vs dubbelwandige uitvoering met vacuüm ertussen$$, $$natuurkunde-havo-2022-ii-koffiepercolator-context5.png$$, 496, $$De ketel van deze percolator is gemaakt van enkelwandig massief roestvrij staal. De fabrikant levert ook een percolator met een dubbele wand van roestvrij staal. De holle ruimte tussen de binnenwand en de buitenwand is vacuüm gemaakt.$$, 'inline');

