   $$natuurkunde-havo-2022-ii-kreukelzone-vraag14.png$$, 496, $$3p 14 Bepaal met behulp van de diagrammen op de uitwerkbijlage de energie die de kreukelzone tijdens de botsing heeft geabsorbeerd. Noteer je antwoord in drie significante cijfers.$$, array['ce4cdbe2-1ad6-4954-a483-f9df232b2df4','8d120b8c-b49b-42ac-9c45-105b5312f970']::uuid[]),
